python3 << 'EOF'
import json
from pathlib import Path

# Find a Scandinavian task result file
results_base = Path('/root/.cache/mteb/results/results')

found = False
for model_dir in results_base.iterdir():
    if not model_dir.is_dir():
        continue

    for hash_dir in model_dir.iterdir():
        if not hash_dir.is_dir():
            continue

        # List JSON files in this directory
        json_files = list(hash_dir.glob('*.json'))
        if json_files:
            # Look for Scandinavian files
            for f in json_files:
                if any(x in f.name for x in ['Bornholm', 'DanFever', 'NorQuad', 'SNL', 'Swedn', 'Swed', 'Norwegian', 'Danish']):
                    print(f"Found: {f.name}")
                    with open(f) as fp:
                        data = json.load(fp)
                    print(json.dumps(data, indent=2)[:1500])
                    found = True
                    break
            if found:
                break
    if found:
        break

if not found:
    # Just show any file structure
    for model_dir in list(results_base.iterdir())[:1]:
        for hash_dir in list(model_dir.iterdir())[:1]:
            json_files = list(hash_dir.glob('*.json'))
            if json_files:
                print(f"Sample file: {json_files[0].name}")
                with open(json_files[0]) as f:
                    data = json.load(f)
                print(json.dumps(data, indent=2)[:1500])
EOF
